#include <stdio.h>

int main(void)
{
    const int readings[] = {6, -1, 6};
    const int length = (int)(sizeof readings / sizeof readings[0]);
    const int target = 6;

    if (length == 0) {
        puts("empty");
        return 0;
    }

    int minimum = readings[0];
    int count = 0;
    for (int i = 0; i < length; ++i) {
        if (readings[i] < minimum) {
            minimum = readings[i];
        }
        if (readings[i] == target) {
            ++count;
        }
    }
    printf("%d %d\n", minimum, count);
    return 0;
}

